  [439134] = { "Crea una bacchetta mistica superiore.", nil, 0xa69d351a, nil, "um" },
  [439155] = { "Ottieni un sigillo incantato dell'innovazione, che ti permette di infliggere fino a $N1 danni e cure aggiuntivi con gli incantesimi e aumenta la potenza d'attacco di $N2 per $D1. Può essere applicato solo fuori dal combattimento.", "Potenziato dall'Innovazione. Infligge fino a $N1 danni e cure aggiuntivi con gli incantesimi e la potenza d'attacco è aumentata di $N2.", 0x5b27e1aa, 0x21bf66a3, "uu" },
  [439431] = { "Infonde il vento nell'arma dello Sciamano. Ogni colpo ha il $N1% di probabilità di fornirti $N2 attacchi aggiuntivi con $N3 di potenza d'attacco in mischia in più. Dura $N4 min.", nil, 0x97843252, nil, "um" },
  [439462] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, riducendone l'armatura di $N3 per $D1.\n\nSebacious Poison beneficia del talento Improved Expose Armor.", nil, 0x2d0ef69d, nil, "um" },
  [439464] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, aumentando del $N3% il tempo tra i suoi attacchi in mischia per $D1.", nil, 0x706228c1, nil, "um" },
  [439465] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, riducendone la potenza d'attacco in mischia di $N3 per $D1.", nil, 0x97dc5dec, nil, "um" },
  [439471] = { nil, "Armatura ridotta di $N1.", nil, 0xaedf6639, "mu" },
  [439472] = { nil, "Intervallo tra gli attacchi aumentato del $N1%.", nil, 0x4f44ab25, "mu" },
  [439473] = { nil, "Potenza d'attacco in mischia ridotta di $N1.", nil, 0x100ea0c6, "mu" },
  [439500] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, riducendone l'armatura di $N3 per $D1. $N5 cariche.\n\nSebacious Poison beneficia del talento Improved Expose Armor.", nil, 0xa3ff8443, nil, "um" },
  [439503] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, riducendone la potenza d'attacco in mischia di $N3 per $D1. $N5 cariche.", nil, 0xebede533, nil, "um" },
  [439505] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, aumentando del $N3% il tempo tra i suoi attacchi in mischia per $D1. $N5 cariche.", nil, 0x05dfb154, nil, "um" },
  [439510] = { "In ⟦Cat Form=Forma Felina⟧ la tua abilità Spazzata diventa Swipe (Cat), e in ⟦Bear Form=Forma d'Orso⟧ Spazzata colpisce fino a $N1 nemici aggiuntivi.\n\nSwipe (Cat)\n$I1\nColpisce con una spazzata i nemici vicini, infliggendo il $N2% dei danni dell'arma e generando $N3 punti combo sul bersaglio attuale.", nil, 0x7f92f961, nil, "um" },
  [439651] = { "Competenza nei tirapugni aumentata di $N1.", nil, 0xcffc0304, nil, "um" },
  [439691] = { "Porta il personaggio a Gnomeregan.", nil, 0x187b8984, nil, "um" },
  [439733] = { "Ti trasformi nell'Albero della Vita. In questa forma aumenti del $N1% le cure ricevute da tutti i membri del gruppo entro $N2 m, le cure di Crescita Rigogliosa aumentano del $N3%, i tuoi incantesimi di cura periodica costano il $N4% in meno, ottieni il $N5% di Spirito in più e il $N6% di Armatura in più, e non puoi lanciare incantesimi offensivi.\n\nL'atto della trasformazione libera l'incantatore dagli effetti di Metamorfosi e di limitazione al movimento.", "Immune agli effetti di Metamorfosi.\nCosto in mana degli incantesimi di cura periodica ridotto del $N1%.\nSpirito aumentato del $N2% e Armatura aumentata del $N3%.\nAumenta del $N4% le cure ricevute da tutti i membri del gruppo entro $N5 m e del $N6% le cure di Crescita Rigogliosa.", 0xc887c72f, 0x3b08cc5b, "uu" },
  [439745] = { "Aumenta del $N2% tutte le cure ricevute dai membri del gruppo entro $N1 m.", "Cure ricevute aumentate del $N1%.", 0x29dc8839, 0xec4c26b6, "uu" },
  [439748] = { "Evochi una raffica di stelle dal cielo per $D1, che colpiscono i bersagli entro $N2 m dalla tua posizione; ognuna infligge $N3 danni da arcano al suo bersaglio e $N4 danni da arcano a tutti gli altri nemici entro $N5 m. Massimo $N6 stelle.\n\nTrasformarsi o montare in sella annulla l'effetto. Qualsiasi effetto che ti fa perdere il controllo del personaggio sopprime l'effetto di Pioggia di Stelle.\n\nBeneficia della maggior parte dei talenti e degli effetti che si attivano da Fuoco Lunare o che lo potenziano, e li attiva.", "Sta evocando stelle dal cielo.", 0x16bd2a8d, 0xe60f8fbc, "uu" },
  [439753] = { "Evochi una raffica di stelle dal cielo su tutti i bersagli entro $N1 m dall'incantatore; ognuna infligge $N2 danni da arcano. Infligge anche $N3 danni da arcano a tutti gli altri nemici entro $N4 m dal bersaglio nemico. Massimo $N5 stelle. Dura $D1.", "Evochi una raffica di stelle dal cielo su tutti i bersagli entro $N1 m dall'incantatore; ognuna infligge $N2 danni da arcano. Infligge anche $N3 danni da arcano a tutti gli altri nemici entro $N4 m dal bersaglio nemico. Massimo $N5 stelle. Dura $D1.", 0xe6e31d13, 0xe6e31d13, "uu" },
  [439756] = { nil, "Massimo $N1 stelle. Dura $D1.", nil, 0x1ae310a7, "mu" },
  [439765] = { "Incidi sul tuo mantello la runa Improved Swipe:\n\n$I1\nIn Forma Felina la tua abilità Spazzata diventa Swipe (Cat), e in Forma d'Orso Spazzata colpisce fino a $N1 nemici aggiuntivi.\n\nSwipe (Cat)\n$I2\nColpisce con una spazzata i nemici vicini, infliggendo il $N2% dei danni dell'arma e generando $N3 punti combo sul bersaglio attuale.", nil, 0xe1173b73, nil, "um" },
  [439766] = { "Ottieni l'abilità Albero della Vita:\n\n$I1\nTi trasformi nell'Albero della Vita. In questa forma aumenti del $N1% le cure ricevute da tutti i membri del gruppo entro $N2 m, le cure di Crescita Rigogliosa aumentano del $N3%, i tuoi incantesimi di cura periodica costano il $N4% in meno, ottieni il $N5% di Spirito in più e il $N6% di Armatura in più, e non puoi lanciare incantesimi offensivi.\n\nL'atto della trasformazione libera l'incantatore dagli effetti di Metamorfosi e di limitazione al movimento.", nil, 0x26efaedb, nil, "um" },
  [439767] = { "Incidi sul tuo mantello la runa Albero della Vita:\n\n$I1\nTi trasformi nell'Albero della Vita. In questa forma aumenti del $N1% le cure ricevute da tutti i membri del gruppo entro $N2 m, le cure di Crescita Rigogliosa aumentano del $N3%, i tuoi incantesimi di cura periodica costano il $N4% in meno, ottieni il $N5% di Spirito in più e il $N6% di Armatura in più, e non puoi lanciare incantesimi offensivi.\n\nL'atto della trasformazione libera l'incantatore dagli effetti di Metamorfosi e di limitazione al movimento.", nil, 0x33ad400e, nil, "um" },
  [439768] = { "Ottieni l'abilità Pioggia di Stelle:\n\n$I1\nEvochi una raffica di stelle dal cielo per $D1, che colpiscono i bersagli entro $N2 m dalla tua posizione; ognuna infligge $N3 danni da arcano al suo bersaglio e $N4 danni da arcano a tutti gli altri nemici entro $N5 m. Massimo $N6 stelle.\n\nTrasformarsi o montare in sella annulla l'effetto. Qualsiasi effetto che ti fa perdere il controllo del personaggio sopprime l'effetto di Pioggia di Stelle.\n\nBeneficia della maggior parte dei talenti e degli effetti che si attivano da Fuoco Lunare o che lo potenziano, e li attiva.", nil, 0x29e92378, nil, "um" },
  [439770] = { "Incidi sul tuo mantello la runa Pioggia di Stelle:\n\n$I1\nEvochi una raffica di stelle dal cielo per $D1, che colpiscono i bersagli entro $N2 m dalla tua posizione; ognuna infligge $N3 danni da arcano al suo bersaglio e $N4 danni da arcano a tutti gli altri nemici entro $N5 m. Massimo $N6 stelle.\n\nTrasformarsi o montare in sella annulla l'effetto. Qualsiasi effetto che ti fa perdere il controllo del personaggio sopprime l'effetto di Pioggia di Stelle.\n\nBeneficia della maggior parte dei talenti e degli effetti che si attivano da Fuoco Lunare o che lo potenziano, e li attiva.", nil, 0x49741463, nil, "um" },
  [439958] = { nil, "Il Blood Loa ricompensa il pericolo.", nil, 0x548d5a62, "mu" },
  [439959] = { "Aumenta fino a $N1 i danni inflitti dagli incantesimi per $D1.", "Danni magici inflitti da incantesimi e abilità aumentati fino a un massimo di $N1.", 0xbfd948e7, 0xa5bf5341, "uu" },
